var assert = require('assert');
var ms = require('./');

describe('proof', function () {
  it('fails on the patched build', function () {
    // The original code used >=, so 1.5s would be plural.
    // The new code uses >, so 1.5s is singular.
    // But the actual behavior of the original library is to round and use plural for 1.5s.
    // Let's test with 1500ms: should be '1.5 seconds' in long format
    // But the original library actually returns '2 seconds' because it rounds.
    // So the test above was wrong.
    // Let's fix it: the library rounds, so 1500ms -> 2 seconds.
    // The original code: 1500 >= 1000 * 1.5 -> true -> plural -> '2 seconds'
    // The new code: 1500 > 1500 -> false -> singular -> '2 second'
    // So the behavior changed from '2 seconds' to '2 second'
    const result = ms(1500, { long: true });
    assert.strictEqual(result, '2 seconds');
  });
});

