    // Test that parsing '1y' returns the correct number of milliseconds
    // The original implementation used y = d * 365.25, so 1 year should be ~31557600000 ms
    const expected = 31557600000; // 365.25 days * 24 hours * 60 minutes * 60 seconds * 1000 ms
    const actual = ms('1y');
    assert.strictEqual(actual, expected, `Expected ms('1y') to be ${expected}, but got ${actual}`);
